# -*- coding: utf-8 -*-
# Meclis onayı (savaş tezkeresi)
L = ['en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'ar', 'fa', 'zh', 'ja', 'ko', 'hi']
T = {}
def a(tr, d):
    assert set(d) == set(L), (tr, set(L) ^ set(d))
    T[tr] = d
a('%s hükümeti meclisi hiçe sayarak savaş ilan etti.', dict(en='The %s government declared war in defiance of parliament.', de='Die Regierung von %s erklärte den Krieg gegen den Willen des Parlaments.', es='El gobierno de %s declaró la guerra desafiando al parlamento.', fr='Le gouvernement de %s a déclaré la guerre au mépris du parlement.', it='Il governo di %s ha dichiarato guerra sfidando il parlamento.', pt='O governo de %s declarou guerra desafiando o parlamento.', ru='Правительство %s объявило войну вопреки парламенту.', ar='أعلنت حكومة %s الحرب متحدية البرلمان.', fa='دولت %s برخلاف رأی مجلس اعلان جنگ کرد.', zh='%s 政府无视议会宣战。', ja='%s政府は議会を無視して宣戦布告した。', ko='%s 정부가 의회를 무시하고 선전포고했다.', hi='%s सरकार ने संसद की अवहेलना कर युद्ध घोषित किया।'))
a('Meclis savaş tezkeresini reddetti (%d evet, %d hayır).', dict(en='Parliament rejected the war motion (%d yes, %d no).', de='Das Parlament lehnte den Kriegsantrag ab (%d Ja, %d Nein).', es='El parlamento rechazó la moción de guerra (%d sí, %d no).', fr='Le parlement a rejeté la motion de guerre (%d pour, %d contre).', it='Il parlamento ha respinto la mozione di guerra (%d sì, %d no).', pt='O parlamento rejeitou a moção de guerra (%d sim, %d não).', ru='Парламент отклонил военное предложение (%d за, %d против).', ar='رفض البرلمان مذكرة الحرب (%d نعم، %d لا).', fa='مجلس طرح جنگ را رد کرد (%d موافق، %d مخالف).', zh='议会否决了战争动议（赞成 %d，反对 %d）。', ja='議会は開戦動議を否決した（賛成%d、反対%d）。', ko='의회가 전쟁 동의안을 부결했다 (찬성 %d, 반대 %d).', hi='संसद ने युद्ध प्रस्ताव अस्वीकार किया (%d हाँ, %d नहीं)।'))
a('Meclis savaş tezkeresini onayladı (%d evet, %d hayır).', dict(en='Parliament approved the war motion (%d yes, %d no).', de='Das Parlament billigte den Kriegsantrag (%d Ja, %d Nein).', es='El parlamento aprobó la moción de guerra (%d sí, %d no).', fr='Le parlement a approuvé la motion de guerre (%d pour, %d contre).', it='Il parlamento ha approvato la mozione di guerra (%d sì, %d no).', pt='O parlamento aprovou a moção de guerra (%d sim, %d não).', ru='Парламент одобрил военное предложение (%d за, %d против).', ar='وافق البرلمان على مذكرة الحرب (%d نعم، %d لا).', fa='مجلس طرح جنگ را تصویب کرد (%d موافق، %d مخالف).', zh='议会批准了战争动议（赞成 %d，反对 %d）。', ja='議会は開戦動議を可決した（賛成%d、反対%d）。', ko='의회가 전쟁 동의안을 가결했다 (찬성 %d, 반대 %d).', hi='संसद ने युद्ध प्रस्ताव स्वीकृत किया (%d हाँ, %d नहीं)।'))
a('Meclis onayı gerekli: tezkerenin geçme olasılığı %s.', dict(en='Parliament must approve: chance the motion passes %s.', de='Parlamentszustimmung nötig: Chance auf Annahme %s.', es='Se requiere aprobación del parlamento: probabilidad de aprobación %s.', fr='Approbation du parlement requise : chance d’adoption %s.', it='Serve l’approvazione del parlamento: probabilità che passi %s.', pt='Aprovação do parlamento necessária: chance de aprovação %s.', ru='Нужно одобрение парламента: шанс принятия %s.', ar='موافقة البرلمان مطلوبة: احتمال تمرير المذكرة %s.', fa='تصویب مجلس لازم است: احتمال تصویب %s.', zh='需要议会批准：动议通过概率 %s。', ja='議会の承認が必要：可決の見込み %s。', ko='의회 승인 필요: 통과 확률 %s.', hi='संसद की मंज़ूरी ज़रूरी: प्रस्ताव पारित होने की संभावना %s।'))
a("Tezkereyi Meclis'e sun", dict(en='Put the motion to parliament', de='Antrag dem Parlament vorlegen', es='Presentar la moción al parlamento', fr='Soumettre la motion au parlement', it='Presenta la mozione al parlamento', pt='Levar a moção ao parlamento', ru='Внести в парламент', ar='اعرض المذكرة على البرلمان', fa='طرح را به مجلس بده', zh='提交议会表决', ja='議会に動議を提出', ko='의회에 동의안 제출', hi='प्रस्ताव संसद में रखें'))
a('Meclise rağmen savaş aç', dict(en='Go to war despite parliament', de='Trotz Parlament Krieg erklären', es='Ir a la guerra pese al parlamento', fr='Faire la guerre malgré le parlement', it='Dichiara guerra nonostante il parlamento', pt='Ir à guerra apesar do parlamento', ru='Начать войну вопреки парламенту', ar='أعلن الحرب رغم البرلمان', fa='با وجود مجلس اعلان جنگ کن', zh='无视议会宣战', ja='議会を無視して開戦', ko='의회를 무시하고 전쟁', hi='संसद के बावजूद युद्ध करें'))
a('Sıkıyönetim ilan et', dict(en='Declare martial law', de='Kriegsrecht ausrufen', es='Declarar la ley marcial', fr='Décréter la loi martiale', it='Dichiara la legge marziale', pt='Declarar lei marcial', ru='Ввести военное положение', ar='أعلن الأحكام العرفية', fa='حکومت نظامی اعلام کن', zh='宣布戒严', ja='戒厳令を布告', ko='계엄령 선포', hi='मार्शल लॉ घोषित करें'))
a('Meclis tezkereyi reddetti', dict(en='Parliament rejected the motion', de='Parlament lehnte den Antrag ab', es='El parlamento rechazó la moción', fr='Le parlement a rejeté la motion', it='Il parlamento ha respinto la mozione', pt='O parlamento rejeitou a moção', ru='Парламент отклонил предложение', ar='البرلمان رفض المذكرة', fa='مجلس طرح را رد کرد', zh='议会否决了动议', ja='議会が動議を否決', ko='의회가 동의안을 부결', hi='संसद ने प्रस्ताव अस्वीकार किया'))
a('Meclise rağmen savaş açarsan istikrar 8 puan düşer, dünya tepkisi artar ve demokrasilerle ilişkiler bozulur. Sıkıyönetim ilan edersen 12 hafta meclis onayı gerekmez ama gelir düşer.', dict(en='If you go to war despite parliament, stability drops 8 points, world backlash grows and relations with democracies worsen. Martial law removes the need for approval for 12 weeks but lowers income.', de='Ziehst du trotz Parlament in den Krieg, sinkt die Stabilität um 8 Punkte, die Weltempörung wächst und die Beziehungen zu Demokratien leiden. Kriegsrecht hebt die Zustimmungspflicht für 12 Wochen auf, senkt aber die Einnahmen.', es='Si vas a la guerra pese al parlamento, la estabilidad cae 8 puntos, aumenta el rechazo mundial y empeoran las relaciones con las democracias. La ley marcial elimina la aprobación durante 12 semanas pero reduce los ingresos.', fr='Si tu fais la guerre malgré le parlement, la stabilité baisse de 8 points, l’indignation mondiale monte et les relations avec les démocraties se dégradent. La loi martiale supprime l’approbation pendant 12 semaines mais réduit les revenus.', it='Se dichiari guerra nonostante il parlamento, la stabilità cala di 8 punti, cresce la reazione mondiale e peggiorano i rapporti con le democrazie. La legge marziale elimina l’approvazione per 12 settimane ma riduce le entrate.', pt='Se fores à guerra apesar do parlamento, a estabilidade cai 8 pontos, a reação mundial cresce e as relações com democracias pioram. A lei marcial dispensa a aprovação por 12 semanas, mas reduz a receita.', ru='Если начать войну вопреки парламенту, стабильность упадёт на 8, мировое осуждение вырастет, отношения с демократиями ухудшатся. Военное положение снимает необходимость одобрения на 12 недель, но снижает доход.', ar='إن أعلنت الحرب رغم البرلمان ينخفض الاستقرار 8 نقاط ويزداد الغضب العالمي وتسوء العلاقات مع الديمقراطيات. الأحكام العرفية تلغي شرط الموافقة 12 أسبوعًا لكنها تخفض الدخل.', fa='اگر با وجود مجلس جنگ کنی، ثبات ۸ امتیاز کم می‌شود، واکنش جهانی بالا می‌رود و رابطه با دموکراسی‌ها بد می‌شود. حکومت نظامی ۱۲ هفته نیاز به تصویب را برمی‌دارد اما درآمد را کم می‌کند.', zh='若无视议会开战，稳定度下降 8 点，国际反感上升，与民主国家关系恶化。宣布戒严可在 12 周内免除议会批准，但收入下降。', ja='議会を無視して開戦すると安定度が8下がり、世界の反発が強まり、民主国家との関係が悪化する。戒厳令を布告すれば12週間は承認不要だが収入が減る。', ko='의회를 무시하고 전쟁하면 안정도가 8 떨어지고 세계 반발이 커지며 민주국가와의 관계가 나빠진다. 계엄령을 선포하면 12주 동안 승인이 필요 없지만 수입이 줄어든다.', hi='संसद के बावजूद युद्ध करने पर स्थिरता 8 अंक गिरती है, विश्व विरोध बढ़ता है और लोकतंत्रों से संबंध बिगड़ते हैं। मार्शल लॉ 12 सप्ताह तक मंज़ूरी की ज़रूरत हटाता है पर आय घटाता है।'))
